func (i *incrementalMergeAccumulator) Result() (*Response, error) {
	if i.data == nil {
		return nil, newMergeError(i.errs)
	}

	if i.pending != 0 || len(i.errs) != 0 {
		i.data.IsComplete = false
	}
	return i.data, newMergeError(i.errs)
}
